function validate([file, n]) {
  if (typeof file !== 'string' || file.length < 1 || file.length > 500) return 'file needs 1 to 500 characters.';
  if (!/^[A-Za-z0-9]+$/.test(file)) return 'file uses only English letters and digits.';
  if (!Number.isInteger(n) || n < 1 || n > 1000) return 'n is a whole number from 1 to 1000.';
  return null;
}

adapter:
function adapt(input, solve, kit) {
  const [file, n] = input;
  let position = 0;
  // The only way to reach the file: up to 4 characters per call, with its own position.
  function read4(buf4) {
    if (!Array.isArray(buf4)) throw new Error('read4 needs an array to fill.');
    let count = 0;
    while (count < 4 && position < file.length) {
      buf4[count] = file[position];
      count++;
      position++;
    }
    return count;
  }
  const reader = solve(read4);
  if (typeof reader !== 'function') throw new Error('read(read4) must return a reader function (buf, n).');
  const buf = new Array(n);
  const count = reader(buf, n);
  if (!Number.isInteger(count) || count < 0 || count > n) throw new Error(`The reader must return a count from 0 to n, not ${count}.`);
  const text = buf.slice(0, count).map(c => typeof c === 'string' ? c : '?').join('');
  if (text !== file.slice(0, count)) return `buf starts with "${text}", which is not the file's first ${count} characters`;
  return count;
}

