function read(read4) {
  return function reader(buf, n) {
    const buf4 = new Array(4);
    let copied = 0;

    while (copied < n) {
      const count = read4(buf4);
      for (let i = 0; i < count && copied < n; i++) {
        buf[copied] = buf4[i];
        copied++;
      }
      if (count < 4) break;
    }
    return copied;
  };
}

