function read(read4) {
  // Pull the whole file into a string first, then copy as much of it as was asked for.
  return (buf, n) => {
    let text = '';
    for (;;) {
      const chunk = [];
      const got = read4(chunk);
      if (got === 0) break;
      text += chunk.slice(0, got).join('');
    }
    const take = Math.min(n, text.length);
    for (let k = 0; k < take; k++) buf[k] = text[k];
    return take;
  };
}

