function generate(rand, size) {
  const pick = k => Math.floor(rand() * k);
  const alphabet = rand() < 0.5 ? 'ab' : 'abcdefghijklmnopqrstuvwxyzABCDEFGHIJKLMNOPQRSTUVWXYZ0123456789';
  const length = size === 'large' ? 500 : 1 + pick(14);
  let file = '';
  for (let i = 0; i < length; i++) file += alphabet[pick(alphabet.length)];
  const roll = rand();
  // Mostly ask for less than the file holds, sometimes exactly all of it, sometimes more.
  const n = roll < 0.6 ? 1 + pick(length) : roll < 0.8 ? length : length + 1 + pick(size === 'large' ? 500 : 10);
  return [file, n];
}
